    private int animationTime = PROGRESS_TIME;
    private int color;
    private boolean rainbow;
    private int cornerRadius;
    private boolean shrink;
    private AnimatorSet indeterminateAnimator;
    public AkTrProgressView(Context context) {
        super(context);
    }
    public AkTrProgressView(Context context, AttributeSet attrs) {
        this(context, attrs, 0);
    }
    public AkTrProgressView(Context context, AttributeSet attrs, int defStyle) {
        super(context, attrs, defStyle);
        initAttributes(attrs, defStyle);
        initPaint();
    }
    private void initAttributes(AttributeSet attrs, int defStyle) {
        animationTime = PROGRESS_TIME;
        maxAlpha = MAX_ALPHA;
        color = Color.BLACK;
        rainbow = false;
        shrink = false;
        cornerRadius = 0;
    }
    public int getMaxAlpha() {
        return maxAlpha;
    }
    public void setMaxAlpha(int maxAlpha) {
        this.maxAlpha = maxAlpha;
    }
    public int getAnimationTime() {
        return animationTime;
    }
    public void setAnimationTime(int animationTime) {
        this.animationTime = animationTime;
    }
    public int getColor() {
        return color;
    }
    public void setColor(int color) {
        this.color = color;
    }
    public boolean isRainbow() {
        return rainbow;
    }
    public void setRainbow(boolean rainbow) {
        this.rainbow = rainbow;
    }
    public int getCornerRadius() {
        return cornerRadius;
    }
    public void setCornerRadius(int cornerRadius) {
        this.cornerRadius = cornerRadius;
    }
    public boolean isShrink() {
        return shrink;
    }
    public void setShrink(boolean shrink) {
        this.shrink = shrink;
    }
    private void initPaint() {
        paint.setAlpha(0);
        paint.setPathEffect(new CornerPathEffect(cornerRadius));
        paint.setColor(color);
        paint.setStyle(Paint.Style.FILL);
        paint.setAntiAlias(true);
    }
    @Override
    protected void onAttachedToWindow() {
        super.onAttachedToWindow();
        startAnimation();
    }
    @Override
    protected void onDetachedFromWindow() {
        super.onDetachedFromWindow();
        stopAnimation();
    }
    @Override
    public void setVisibility(int visibility) {
        int currentVisibility = getVisibility();
        super.setVisibility(visibility);
        if (visibility != currentVisibility) {
            if (visibility == View.VISIBLE) {
                resetAnimator();
            } else if (visibility == View.GONE || visibility == View.INVISIBLE) {
                stopAnimation();
            }
        }
    }
    private void startAnimation() {
        resetAnimator();
    }
    private void stopAnimation() {
        actualProgress = 0;
        if (indeterminateAnimator != null) {
            indeterminateAnimator.cancel();
            indeterminateAnimator = null;
        }
    }
    private void resetAnimator() {
        if (indeterminateAnimator != null && indeterminateAnimator.isRunning()) {
            indeterminateAnimator.cancel();
        }
        ValueAnimator progressAnimator = ValueAnimator.ofFloat(0, MAX_PROGRESS_VALUE);
        progressAnimator.setDuration(animationTime);
        progressAnimator.setInterpolator(new LinearInterpolator());
        progressAnimator.addUpdateListener(new ValueAnimator.AnimatorUpdateListener() {
            @Override
            public void onAnimationUpdate(ValueAnimator animation) {
                actualProgress = (Float) animation.getAnimatedValue();
                invalidate();
            }
        });
        indeterminateAnimator = new AnimatorSet();
        indeterminateAnimator.play(progressAnimator);
        indeterminateAnimator.addListener(new AnimatorListenerAdapter() {
            boolean wasCancelled = false;
            @Override
            public void onAnimationCancel(Animator animation) {
                wasCancelled = true;
            }
            @Override
            public void onAnimationEnd(Animator animation) {
                if (!wasCancelled) {
                    resetAnimator();
                }
            }
        });
        indeterminateAnimator.start();
    }
    @Override
