public class MaterialSwitch {
    private int ms_bgc_off = 0xFF000000; // Preto
    private int ms_bgc_on = 0xFF4CAF50;  // Verde
    private int ms_tc_off = 0xFFFFFFFF;  // Branco
    private int ms_tc_on = 0xFFFFFFFF;   // Branco
    private boolean ms_isAnimated = true;
    private int default_width;
    private int default_height;
    private int va_duration = 250;
    private boolean isClickable = true;
    private boolean isChecked = false; // Estado do switch

    public LinearLayout ms_background;
    public LinearLayout ms_thumb;
    private LinearLayout ms_switch;
    private LinearLayout RETURNER;
    private Context context;

    public MaterialSwitch(Context context) {
        if (context == null) throw new IllegalArgumentException("Context não pode ser null!");
        this.context = context;
        this.default_width = dp(70);
        this.default_height = default_width / 2;
    }

    public void create(Activity activity, String switchId, int width, int height) {
        if (activity == null) throw new IllegalArgumentException("Activity não pode ser null!");

        View switchView = activity.findViewById(activity.getResources().getIdentifier(switchId, "id", activity.getPackageName()));
        if (switchView != null) {
            ViewGroup parent = (ViewGroup) switchView.getParent();
            if (parent != null) {
                ViewGroup.LayoutParams params = switchView.getLayoutParams();
                int index = parent.indexOfChild(switchView);
                parent.removeView(switchView);

                LinearLayout newContainer = new LinearLayout(context);
                newContainer.setLayoutParams(params);
                newContainer.setId(View.generateViewId());

                parent.addView(newContainer, index);

                this.default_width = dp(width);
                this.default_height = dp(height);

                createSwitch(newContainer);
            }
        }
    }

    private void createSwitch(LinearLayout view) {
        ms_background = new LinearLayout(context);
        ms_thumb = new LinearLayout(context);
        ms_switch = new LinearLayout(context);
        RETURNER = view;

        ms_switch.setLayoutParams(new LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT));
        setLayoutParams(ms_background, default_width, default_height);
        setLayoutParams(ms_thumb, default_height - dp(10), default_height - dp(10));

        ms_switch.addView(ms_background);
        ms_background.addView(ms_thumb);
        RETURNER.addView(ms_switch);

        padding(ms_switch, 0);
        padding(ms_background, dp(5));
        padding(RETURNER, 0);

        RETURNER.setBackgroundColor(Color.TRANSPARENT);

        // Ajustando a cor inicial corretamente
        setRadius(ms_background, 999, ms_bgc_off);
        setRadius(ms_thumb, 999, ms_tc_off);

        RETURNER.setOnClickListener(_view -> toggleSwitch());
    }

    private void toggleSwitch() {
        if (ms_isAnimated) {
            if (isClickable) {
                isClickable = false;
                isChecked = !isChecked; // Alterna o estado

                ValueAnimator va1 = ValueAnimator.ofArgb(getColor(ms_thumb, isChecked ? ms_tc_off : ms_tc_on), isChecked ? ms_tc_on : ms_tc_off);
                va1.addUpdateListener(animator -> setRadius(ms_thumb, 999, (int) animator.getAnimatedValue()));
                va1.setDuration(va_duration);
                va1.start();

                ValueAnimator va2 = ValueAnimator.ofArgb(getColor(ms_background, isChecked ? ms_bgc_off : ms_bgc_on), isChecked ? ms_bgc_on : ms_bgc_off);
                va2.addUpdateListener(animator -> setRadius(ms_background, 999, (int) animator.getAnimatedValue()));
                va2.setDuration(va_duration);
                va2.start();

                ValueAnimator va3 = ValueAnimator.ofFloat(getThumbX(), isChecked ? default_height : dp(0));
                va3.addUpdateListener(animator -> setThumbX((float) animator.getAnimatedValue()));
                va3.setDuration(va_duration);
                va3.start();

                new Handler().postDelayed(() -> isClickable = true, va_duration);
            }
        } else {
            isChecked = !isChecked; // Alterna o estado sem animação
            setThumbX(isChecked ? default_height : 0);
            setRadius(ms_background, 999, isChecked ? ms_bgc_on : ms_bgc_off);
            setRadius(ms_thumb, 999, isChecked ? ms_tc_on : ms_tc_off);
        }
    }

    public void setChecked(boolean checked) {
        if (checked != isChecked) {
            toggleSwitch();
        }
    }

    public boolean isChecked() {
        return isChecked;
    }

    public void setThumbX(float x) {
        setX(ms_thumb, x);
    }

    public float getThumbX() {
        return ms_thumb.getTranslationX();
    }

    private int dp(int _input) {
        if (context == null) throw new IllegalStateException("Context não pode ser null ao chamar dp()!");
        return (int) TypedValue.applyDimension(TypedValue.COMPLEX_UNIT_DIP, _input, context.getResources().getDisplayMetrics());
    }

    private void setLayoutParams(View view, int width, int height) {
        view.setLayoutParams(new LinearLayout.LayoutParams(width, height));
    }

    private void setRadius(View view, int radius, int color) {
        GradientDrawable gd = new GradientDrawable();
        gd.setColor(color);
        gd.setCornerRadius(radius);
        view.setBackground(gd);
    }

    private void padding(View view, int value) {
        view.setPadding(value, value, value, value);
    }

    private void setX(View view, float value) {
        view.setX(value + dp(5));
    }

    private int getColor(View view, int defaultColor) {
        Drawable drawable = view.getBackground();
        if (drawable instanceof ColorDrawable) {
            return ((ColorDrawable) drawable).getColor();
        }
        return defaultColor;
    }

    public void setBackgroundColor(int color) {
        ms_bgc_off = color;
        setRadius(ms_background, 999, color); // Atualizando a cor imediatamente
    }

    public void setToggledBackgroundColor(int color) {
        ms_bgc_on = color;
    }

    public void setThumbColor(int color) {
        ms_tc_off = color;
        setRadius(ms_thumb, 999, color); // Atualizando a cor imediatamente
    }

    public void setToggledThumbColor(int color) {
        ms_tc_on = color;
    }

    public void enableAnimations(boolean value) {
        ms_isAnimated = value;
    }

    public void setDuration(int value) {
        va_duration = value;
    }
}

